// Aquí calculamos la ganancia real para BASAR Y PERFUMERIA XIMENA

export const calcularGananciaReal = (ventas) => {
    // Suma la ganancia de cada venta realizada
    const gananciaTotal = ventas.reduce((acc, venta) => acc + (Number(venta.ganancia) || 0), 0);
    
    // Muestra el resultado en la consola (F12) para que solo tú lo veas
    console.log("------------------------------------");
    console.log("💰 REPORTE DE GANANCIA NETA: S/. " + gananciaTotal.toFixed(2));
    console.log("------------------------------------");
    
    return gananciaTotal;
};

// Función para avisar si el stock es peligroso
export const verificarAlertasStock = (productos) => {
    const criticos = productos.filter(p => p.stock <= 2);
    if (criticos.length > 0) {
        console.warn("⚠️ TIENES " + criticos.length + " PRODUCTOS CASI AGOTADOS");
    }
};// Función para que el sistema hable
export const hablarSistema = (mensaje) => {
    const voz = new SpeechSynthesisUtterance(mensaje);
    voz.lang = 'es-ES';
    window.speechSynthesis.speak(voz);
};

// Función de "Escudo" contra borrados accidentales
export const backupSeguro = (datos) => {
    const backupKey = 'BACKUP_SEGURIDAD_BASAR Y PERFUMERIA XIMENA';
    localStorage.setItem(backupKey, JSON.stringify(datos));
};