const reproducirSonidoAlerta = () => {
  // Verifica si el usuario actual es el administrador (ajústalo a tu variable de usuario si es necesario)
  if (loginData?.usuario !== "Milagros") {
    return; // Si no es el administrador, no suena nada
  }

  try {
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    
    // Simulamos el tono característico tipo "Ding" de mensaje del iPhone
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();

    osc.type = 'sine';
    
    // Frecuencias altas y limpias para imitar el tono de mensaje de iOS
    osc.frequency.setValueAtTime(1318.51, audioCtx.currentTime); // Nota E6 (aguda inicial)
    osc.frequency.setValueAtTime(2637.02, audioCtx.currentTime + 0.08); // Nota E7 (brillo característico)

    // Volumen inicial fuerte pero controlado con un desvanecimiento suave para que suene claro
    gain.gain.setValueAtTime(0.6, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.6);

    osc.connect(gain);
    gain.connect(audioCtx.destination);

    osc.start();
    osc.stop(audioCtx.currentTime + 0.6);

  } catch (e) {
    console.log("Audio no soportado");
  }
};
